class Field(Flowable):
 count=0
 def __init__(self,label,height=28,value=''):
  Flowable.__init__(self);Field.count+=1;self.key='field_%d'%Field.count;self.label=label;self.box=height;self.height=height+23;self.width=475;self.value=value
 def draw(self):
  c=self.canv;c.setFont('Helvetica-Bold',9);c.setFillColor(colors.HexColor('#263b4d'));c.drawString(0,self.box+7,self.label)
  x,y=c.absolutePosition(0,0)
  c.acroForm.textfield(name=self.key,tooltip=self.label,x=x,y=y,width=475,height=self.box,value=self.value,fontName='Helvetica',fontSize=10,borderWidth=.7,borderColor=colors.HexColor('#9db4c4'),fillColor=colors.HexColor('#fffaf0'),textColor=colors.black,fieldFlags='multiline' if self.box>30 else '',forceBorder=True,maxlen=4000)
def F(label,height=28,value=''):return Field(label,height,value)
